/*
 * Owl BLE protocol v1: constants and byte layouts.
 *
 * protocol/ble-protocol.md is the contract; tools/owlproto.py is the reference
 * implementation. Everything here is plain C with no Zephyr dependency so the
 * native_sim tests can check it against vectors generated by owlproto.py.
 *
 * All multi-byte integers on the wire (and in flash) are little-endian. We never
 * memcpy structs onto the wire: the pack/unpack helpers write byte by byte, so the
 * layout does not depend on compiler padding or CPU endianness.
 */

#ifndef OWL_PROTO_H_
#define OWL_PROTO_H_

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define OWL_PROTO_VER       1
#define OWL_SEGMENT_VERSION 1

/* 128-bit UUIDs: a269xxxx-8c8b-40f7-a91b-3ffa7ab560b9 (§2). */
#define OWL_UUID_SERVICE 0x0001
#define OWL_UUID_STATUS  0x0002
#define OWL_UUID_CONTROL 0x0003
#define OWL_UUID_DATA    0x0004

#define OWL_ATT_MTU          247
#define OWL_ATT_PAYLOAD      (OWL_ATT_MTU - 3)                  /* 244 */
#define OWL_DATA_HDR_LEN     8                                  /* segment_id, offset */
#define OWL_DATA_CHUNK_MAX   (OWL_ATT_PAYLOAD - OWL_DATA_HDR_LEN) /* 236 */

/* CONTROL opcodes (§2.2). */
enum owl_op {
	OWL_OP_TIME_SYNC = 0x01,
	OWL_OP_LIST_SEGMENTS = 0x02,
	OWL_OP_FETCH_SEGMENT = 0x03,
	OWL_OP_ACK_SEGMENT = 0x04,
	OWL_OP_ABORT = 0x05,
	OWL_OP_SET_RECORDING = 0x06,
	OWL_OP_UNPAIR = 0x07,
	OWL_OP_SET_CONFIG = 0x10,
};
#define OWL_RESPONSE_BIT 0x80

enum owl_result {
	OWL_RESULT_OK = 0,
	OWL_RESULT_UNKNOWN_OP = 1,
	OWL_RESULT_BAD_LENGTH = 2,
	OWL_RESULT_NO_SEGMENT = 3,
	OWL_RESULT_CRC_MISMATCH = 4,
	OWL_RESULT_BUSY = 5,
};

enum owl_config_key {
	OWL_CFG_OPUS_BITRATE = 1,
	OWL_CFG_VAD_SENSITIVITY = 2,
	OWL_CFG_SEGMENT_MAX_S = 3,
};

/* Segment header (§3.1). */
#define OWL_SEG_MAGIC   "OWLS"
#define OWL_SEG_HDR_LEN 32

enum owl_seg_type {
	OWL_SEG_AUDIO = 1,
	OWL_SEG_EVENTS = 2,
};

enum owl_codec {
	OWL_CODEC_PCM16 = 0,
	OWL_CODEC_OPUS = 1,
};

/* Events (§3.3) and their cause arguments. */
enum owl_event {
	OWL_EVT_BOOKMARK = 1,
	OWL_EVT_RECORDING_OFF = 2,
	OWL_EVT_RECORDING_ON = 3,
	OWL_EVT_STORAGE_FULL = 4,
	OWL_EVT_BATTERY_LOW = 5,
	OWL_EVT_POWER_OFF = 6,
	OWL_EVT_POWER_ON = 7,
};

enum owl_cause {
	OWL_CAUSE_BUTTON = 0,
	OWL_CAUSE_APP = 1,
	OWL_CAUSE_BATTERY = 2,
	OWL_CAUSE_CHARGED = 3,
	OWL_CAUSE_OTHER = 4,
};

#define OWL_EVENT_REC_LEN 10 /* uptime_ms u64, event u8, arg u8 */

/* STATUS characteristic (§2.1). */
#define OWL_STATUS_LEN 24

#define OWL_FLAG_CHARGING     (1U << 0) /* always 0: the board has no charge-status pin */
#define OWL_FLAG_RECORDING    (1U << 1) /* user has recording switched on */
#define OWL_FLAG_STORAGE_LOW  (1U << 2) /* >= 90 % used */
#define OWL_FLAG_STORAGE_FULL (1U << 3) /* recording paused because flash is full */
#define OWL_FLAG_PAIRING_OPEN (1U << 4) /* a new pairing would be accepted now (§2.4) */

struct owl_status {
	uint8_t fw_ver[3];
	uint16_t battery_mv;
	uint8_t flags;
	uint32_t storage_used_kb;
	uint32_t storage_total_kb;
	uint16_t pending_segments;
	uint32_t boot_count;
};

struct owl_seg_header {
	uint8_t version;
	uint8_t type;
	uint8_t codec;
	uint8_t frame_ms;
	uint32_t id;
	uint32_t boot_count;
	uint64_t start_uptime_ms;
	uint16_t sample_rate_div100;
	uint8_t channels;
	uint32_t payload_len;
};

/* One LIST_SEGMENTS entry: id u32, type u8, size u32. */
#define OWL_LIST_ENTRY_LEN 9
/* (244 - op - seq - result - count) / 9 = 26 */
#define OWL_LIST_MAX ((OWL_ATT_PAYLOAD - 4) / OWL_LIST_ENTRY_LEN)

struct owl_list_entry {
	uint32_t id;
	uint8_t type;
	uint32_t size; /* whole segment = header + payload */
};

/* Little-endian helpers. */
static inline void owl_put_u16(uint8_t *p, uint16_t v)
{
	p[0] = (uint8_t)v;
	p[1] = (uint8_t)(v >> 8);
}

static inline void owl_put_u32(uint8_t *p, uint32_t v)
{
	p[0] = (uint8_t)v;
	p[1] = (uint8_t)(v >> 8);
	p[2] = (uint8_t)(v >> 16);
	p[3] = (uint8_t)(v >> 24);
}

static inline void owl_put_u64(uint8_t *p, uint64_t v)
{
	owl_put_u32(p, (uint32_t)v);
	owl_put_u32(p + 4, (uint32_t)(v >> 32));
}

static inline uint16_t owl_get_u16(const uint8_t *p)
{
	return (uint16_t)(p[0] | (p[1] << 8));
}

static inline uint32_t owl_get_u32(const uint8_t *p)
{
	return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) |
	       ((uint32_t)p[3] << 24);
}

static inline uint64_t owl_get_u64(const uint8_t *p)
{
	return (uint64_t)owl_get_u32(p) | ((uint64_t)owl_get_u32(p + 4) << 32);
}

void owl_status_pack(const struct owl_status *s, uint8_t out[OWL_STATUS_LEN]);

void owl_seg_header_pack(const struct owl_seg_header *h, uint8_t out[OWL_SEG_HDR_LEN]);
/* Returns 0, or -1 if the magic is wrong. */
int owl_seg_header_unpack(const uint8_t in[OWL_SEG_HDR_LEN], struct owl_seg_header *h);

/* Fills the fixed fields of a new header (version, sample rate, channels). */
void owl_seg_header_init(struct owl_seg_header *h, uint8_t type, uint8_t codec,
			 uint8_t frame_ms, uint32_t id, uint32_t boot_count,
			 uint64_t start_uptime_ms);

void owl_event_pack(uint64_t uptime_ms, uint8_t event, uint8_t arg,
		    uint8_t out[OWL_EVENT_REC_LEN]);

void owl_list_entry_pack(const struct owl_list_entry *e, uint8_t out[OWL_LIST_ENTRY_LEN]);

/* Standard CRC-32 (IEEE 802.3, same as zlib.crc32). Start with crc = 0. */
uint32_t owl_crc32(uint32_t crc, const void *data, size_t len);

#endif /* OWL_PROTO_H_ */
